import re
import sqlite3
from collections import defaultdict
from dataclasses import dataclass
from typing import Dict, List, Tuple, Any, Optional

# Vector
try:
    from pymilvus import connections, Collection, utility
    MILVUS_AVAILABLE = True
except Exception:
    MILVUS_AVAILABLE = False

try:
    from sentence_transformers import SentenceTransformer
    ST_AVAILABLE = True
except Exception:
    ST_AVAILABLE = False


# --------------------------
# Fixed configs (as required)
# --------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

MILVUS_CFG = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

NEO4J_CFG = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# --------------------------
# Helpers
# --------------------------

def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def detect_table(conn: sqlite3.Connection, preferred: str) -> str:
    """Return preferred if exists; else try to find a close match."""
    cur = conn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = {r[0] for r in cur.fetchall()}
    if preferred in tables:
        return preferred
    # naive fallback
    for t in tables:
        if t.lower() == preferred.lower():
            return t
    # common alternates
    alts = {
        'business': ['businesses'],
        'review': ['reviews'],
        'user': ['users'],
        'tip': ['tips']
    }
    for alt in alts.get(preferred, []):
        if alt in tables:
            return alt
        for t in tables:
            if t.lower() == alt.lower():
                return t
    raise RuntimeError(f"Could not find table '{preferred}' in {tables}")


def safe_like_any(field: str, keywords: List[str]) -> Tuple[str, List[str]]:
    """Build (field LIKE ? OR field LIKE ? ...) and params."""
    conds = []
    params = []
    for kw in keywords:
        conds.append(f"{field} LIKE ?")
        params.append(f"%{kw}%")
    return ("(" + " OR ".join(conds) + ")"), params


def normalize_elite(elite_val: Any) -> str:
    if elite_val is None:
        return ""
    s = str(elite_val).strip()
    return s


def short_snippet(text: str, keywords: List[str], width: int = 220) -> str:
    if not text:
        return ""
    lower = text.lower()
    hits = []
    for kw in keywords:
        i = lower.find(kw.lower())
        if i >= 0:
            hits.append(i)
    if not hits:
        return (text[:width] + ("..." if len(text) > width else ""))
    i = min(hits)
    start = max(0, i - width // 3)
    end = min(len(text), start + width)
    snippet = text[start:end].strip()
    if start > 0:
        snippet = "..." + snippet
    if end < len(text):
        snippet = snippet + "..."
    return snippet


@dataclass
class Hit:
    kind: str  # 'review' or 'tip'
    business_id: str
    user_id: Optional[str]
    ref_id: Optional[str]  # review_id or tip_id
    score: float


# --------------------------
# Core logic
# --------------------------

def fetch_tucson_bookstores(conn_business: sqlite3.Connection) -> List[Dict[str, Any]]:
    tb = detect_table(conn_business, 'business')
    q = f"""
    SELECT business_id, name, address, city, state, stars, review_count, categories
    FROM {tb}
    WHERE city = ?
      AND (categories LIKE ? OR categories LIKE ?)
    """
    cur = conn_business.cursor()
    cur.execute(q, ('Tucson', '%Bookstore%', '%Bookstores%'))
    rows = [dict(r) for r in cur.fetchall()]
    return rows


def milvus_connect() -> bool:
    if not MILVUS_AVAILABLE:
        return False
    try:
        connections.connect(
            alias='default',
            host=MILVUS_CFG['milvus_host'],
            port=MILVUS_CFG['milvus_port']
        )
        return True
    except Exception:
        return False


def get_embedding_model():
    if not ST_AVAILABLE:
        return None
    # A solid default; change if you used a different model when creating vectors
    return SentenceTransformer('sentence-transformers/all-MiniLM-L6-v2')


def milvus_collection_exists(name: str) -> bool:
    try:
        return utility.has_collection(name)
    except Exception:
        return False


def milvus_search_hits(
    collection_name: str,
    query_texts: List[str],
    topk_per_query: int = 200,
    score_higher_is_better: bool = True
) -> List[Hit]:
    """
    Search Milvus and return Hit list.

    Assumptions about collection fields (best-effort):
      - vector field name likely 'embedding' or 'vector'
      - metadata fields may include: business_id, user_id, review_id/tip_id

    If fields are not found, returns empty list.
    """
    if not milvus_collection_exists(collection_name):
        return []

    model = get_embedding_model()
    if model is None:
        return []

    col = Collection(collection_name)
    col.load()

    # detect vector field
    schema_fields = {f.name: f for f in col.schema.fields}
    vec_field = None
    for cand in ['embedding', 'vector', 'emb', 'sentence_embedding']:
        if cand in schema_fields:
            vec_field = cand
            break
    if vec_field is None:
        # pick first FLOAT_VECTOR
        for f in col.schema.fields:
            if str(f.dtype).lower().endswith('float_vector'):
                vec_field = f.name
                break
    if vec_field is None:
        return []

    # output fields
    output_fields = []
    for cand in ['business_id', 'user_id', 'review_id', 'tip_id', 'id']:
        if cand in schema_fields:
            output_fields.append(cand)

    # choose metric params (unknown index settings; provide common defaults)
    search_params = {
        'metric_type': 'IP',
        'params': {'nprobe': 16}
    }

    hits: List[Hit] = []
    vectors = model.encode(query_texts, normalize_embeddings=True).tolist()

    res = col.search(
        data=vectors,
        anns_field=vec_field,
        param=search_params,
        limit=topk_per_query,
        output_fields=output_fields
    )

    # res is a list (per query) of hits
    for per_query in res:
        for h in per_query:
            ent = getattr(h, 'entity', None)
            score = float(h.score)
            if ent is None:
                continue

            business_id = ent.get('business_id') if 'business_id' in output_fields else None
            user_id = ent.get('user_id') if 'user_id' in output_fields else None
            ref_id = None
            kind = 'review'
            if 'review_id' in output_fields and ent.get('review_id') is not None:
                ref_id = ent.get('review_id')
                kind = 'review'
            elif 'tip_id' in output_fields and ent.get('tip_id') is not None:
                ref_id = ent.get('tip_id')
                kind = 'tip'
            elif 'id' in output_fields and ent.get('id') is not None:
                # last resort
                ref_id = str(ent.get('id'))

            if business_id is None:
                continue

            hits.append(Hit(kind=kind, business_id=str(business_id), user_id=str(user_id) if user_id is not None else None, ref_id=str(ref_id) if ref_id is not None else None, score=score))

    return hits


def keyword_fallback_hits(
    conn_review: sqlite3.Connection,
    conn_tip: sqlite3.Connection,
    candidate_business_ids: List[str],
    keywords: List[str]
) -> List[Hit]:
    """Fallback when Milvus isn't available: use LIKE keyword search in SQLite review/tip text."""
    tr = detect_table(conn_review, 'review')
    tt = detect_table(conn_tip, 'tip')

    cond, params = safe_like_any('text', keywords)
    # chunk business_ids to avoid SQLite variable limit
    def chunks(lst, n=400):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    hits: List[Hit] = []

    for chunk in chunks(candidate_business_ids):
        placeholders = ','.join(['?'] * len(chunk))

        q1 = f"SELECT review_id, business_id, user_id FROM {tr} WHERE business_id IN ({placeholders}) AND {cond}"
        cur = conn_review.cursor()
        cur.execute(q1, chunk + params)
        for r in cur.fetchall():
            hits.append(Hit(kind='review', business_id=r['business_id'], user_id=r['user_id'], ref_id=r['review_id'], score=1.0))

        q2 = f"SELECT rowid AS tip_rowid, business_id, user_id FROM {tt} WHERE business_id IN ({placeholders}) AND {cond}"
        cur = conn_tip.cursor()
        cur.execute(q2, chunk + params)
        for r in cur.fetchall():
            # Yelp tip.json has no tip_id in original; many SQLite loaders use rowid
            hits.append(Hit(kind='tip', business_id=r['business_id'], user_id=r['user_id'], ref_id=str(r['tip_rowid']), score=1.0))

    return hits


def fetch_review_texts(conn_review: sqlite3.Connection, review_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    tr = detect_table(conn_review, 'review')
    if not review_ids:
        return {}

    # chunk
    out: Dict[str, Dict[str, Any]] = {}
    def chunks(lst, n=400):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    for chunk in chunks(review_ids):
        placeholders = ','.join(['?'] * len(chunk))
        q = f"SELECT review_id, business_id, user_id, stars, date, text FROM {tr} WHERE review_id IN ({placeholders})"
        cur = conn_review.cursor()
        cur.execute(q, chunk)
        for r in cur.fetchall():
            out[str(r['review_id'])] = dict(r)
    return out


def fetch_tip_texts(conn_tip: sqlite3.Connection, tip_ref_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    """
    Tips often lack a stable tip_id in Yelp; loaders may use rowid.
    We'll try to query by rowid if numeric-like.
    """
    tt = detect_table(conn_tip, 'tip')
    if not tip_ref_ids:
        return {}

    numeric_ids = [rid for rid in tip_ref_ids if rid is not None and re.fullmatch(r"\d+", str(rid))]
    out: Dict[str, Dict[str, Any]] = {}
    if not numeric_ids:
        return out

    def chunks(lst, n=400):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    for chunk in chunks(numeric_ids):
        placeholders = ','.join(['?'] * len(chunk))
        q = f"SELECT rowid AS tip_rowid, business_id, user_id, date, text, likes FROM {tt} WHERE rowid IN ({placeholders})"
        cur = conn_tip.cursor()
        cur.execute(q, chunk)
        for r in cur.fetchall():
            out[str(r['tip_rowid'])] = dict(r)
    return out


def fetch_users(conn_user: sqlite3.Connection, user_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    tu = detect_table(conn_user, 'user')
    if not user_ids:
        return {}

    out: Dict[str, Dict[str, Any]] = {}

    def chunks(lst, n=400):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    # de-dup
    user_ids = list({uid for uid in user_ids if uid})

    for chunk in chunks(user_ids):
        placeholders = ','.join(['?'] * len(chunk))
        q = f"SELECT user_id, name, elite, review_count, average_stars FROM {tu} WHERE user_id IN ({placeholders})"
        cur = conn_user.cursor()
        cur.execute(q, chunk)
        for r in cur.fetchall():
            out[str(r['user_id'])] = dict(r)
    return out


def classify_themes(text: str) -> List[str]:
    t = (text or '').lower()
    themes = []
    if any(k in t for k in ['cozy', 'cosy', 'warm', 'comfy', 'comfortable', 'nook', 'quiet', 'vibe']):
        themes.append('cozy')
    if any(k in t for k in ['hidden', 'tucked away', 'off the beaten', 'secret', 'gem', 'hole in the wall']):
        themes.append('hidden')
    if any(k in t for k in ['rare', 'first edition', 'signed', 'collect', 'out of print', 'antiquarian']):
        themes.append('rare_books')
    if any(k in t for k in ['event', 'reading', 'author', 'book club', 'signing', 'workshop', 'open mic']):
        themes.append('events')
    return themes


def main():
    # --- Connect SQLite ---
    conn_business = connect_sqlite(sqlite_paths['business'])
    conn_review = connect_sqlite(sqlite_paths['review'])
    conn_tip = connect_sqlite(sqlite_paths['tip'])
    conn_user = connect_sqlite(sqlite_paths['user'])

    # --- Step 1: candidate bookstores in Tucson ---
    businesses = fetch_tucson_bookstores(conn_business)
    if not businesses:
        print('No Tucson bookstores found in business.db (check categories/city).')
        return

    business_by_id = {b['business_id']: b for b in businesses}
    candidate_ids = list(business_by_id.keys())

    # --- Step 2: semantic retrieval via Milvus (fallback to keyword LIKE) ---
    query_texts = [
        'cozy hidden atmosphere bookstore',
        'rare books first editions signed antiquarian',
        'bookstore events author readings book club signing'
    ]
    keywords = [
        'cozy','cosy','hidden','tucked away','quiet','warm','nook','gem',
        'rare','first edition','signed','out of print','antiquarian',
        'event','reading','author','book club','signing','workshop','open mic'
    ]

    hits: List[Hit] = []
    milvus_ok = milvus_connect()

    if milvus_ok and ST_AVAILABLE:
        try:
            # reviews
            review_hits = milvus_search_hits(MILVUS_CFG['milvus_collections']['reviews'], query_texts, topk_per_query=250)
            # tips
            tip_hits = milvus_search_hits(MILVUS_CFG['milvus_collections']['tips'], query_texts, topk_per_query=250)
            hits = review_hits + tip_hits
        except Exception as e:
            print(f"Milvus search failed, fallback to keyword search. Error: {e}")
            hits = keyword_fallback_hits(conn_review, conn_tip, candidate_ids, keywords)
    else:
        hits = keyword_fallback_hits(conn_review, conn_tip, candidate_ids, keywords)

    # Keep only hits in Tucson bookstores
    hits = [h for h in hits if h.business_id in business_by_id]
    if not hits:
        print('No matching review/tip hits found for cozy/hidden/rare/events among Tucson bookstores.')
        return

    # --- Step 3: fetch texts + users; filter elite evidence ---
    review_ids = [h.ref_id for h in hits if h.kind == 'review' and h.ref_id]
    tip_ref_ids = [h.ref_id for h in hits if h.kind == 'tip' and h.ref_id]

    review_map = fetch_review_texts(conn_review, list({rid for rid in review_ids if rid}))
    tip_map = fetch_tip_texts(conn_tip, list({tid for tid in tip_ref_ids if tid}))

    # collect user_ids from maps/hits
    user_ids = []
    for h in hits:
        if h.user_id:
            user_ids.append(h.user_id)
    for r in review_map.values():
        if r.get('user_id'):
            user_ids.append(r['user_id'])
    for t in tip_map.values():
        if t.get('user_id'):
            user_ids.append(t['user_id'])

    user_map = fetch_users(conn_user, user_ids)

    # Aggregate per business
    agg = defaultdict(lambda: {
        'elite_hit_count': 0,
        'elite_users': set(),
        'total_hit_count': 0,
        'score_sum': 0.0,
        'evidence': []  # list of dict
    })

    for h in hits:
        b_id = h.business_id
        text = ''
        user_id = h.user_id

        if h.kind == 'review':
            r = review_map.get(h.ref_id or '', None)
            if r:
                text = r.get('text', '') or ''
                user_id = r.get('user_id') or user_id
        else:
            t = tip_map.get(h.ref_id or '', None)
            if t:
                text = t.get('text', '') or ''
                user_id = t.get('user_id') or user_id

        u = user_map.get(user_id or '', None)
        elite = normalize_elite(u.get('elite') if u else '')
        is_elite = bool(elite)

        themes = classify_themes(text)
        # Require at least atmosphere (cozy/hidden) AND (rare_books/events) preference
        # But keep some flexibility: if text hits rare/events without cozy, still include; ranking will favor combined themes
        if not themes:
            continue

        agg[b_id]['total_hit_count'] += 1
        agg[b_id]['score_sum'] += float(h.score)

        if is_elite:
            agg[b_id]['elite_hit_count'] += 1
            agg[b_id]['elite_users'].add(user_id)

        # store limited evidence
        if len(agg[b_id]['evidence']) < 8:
            uname = u.get('name') if u else None
            snippet = short_snippet(text, keywords)
            agg[b_id]['evidence'].append({
                'kind': h.kind,
                'score': float(h.score),
                'user_id': user_id,
                'user_name': uname,
                'elite': elite,
                'themes': themes,
                'snippet': snippet
            })

    # Remove businesses without any elite evidence, since user emphasized elite recommendations
    # If you want more recall, comment this block and keep all.
    agg = {bid: v for bid, v in agg.items() if v['elite_hit_count'] > 0}
    if not agg:
        print('Found cozy/hidden/rare/events mentions, but none from elite users among Tucson bookstores.')
        return

    # --- Step 4: ranking ---
    ranked = []
    for bid, v in agg.items():
        b = business_by_id[bid]
        avg_score = v['score_sum'] / max(1, v['total_hit_count'])
        elite_user_count = len(v['elite_users'])
        # ranking heuristic
        rank_score = (
            4.0 * elite_user_count +
            1.5 * v['elite_hit_count'] +
            0.25 * v['total_hit_count'] +
            0.6 * float(b.get('stars') or 0) +
            0.02 * float(b.get('review_count') or 0) +
            0.5 * avg_score
        )
        ranked.append((rank_score, bid, avg_score, elite_user_count))

    ranked.sort(reverse=True, key=lambda x: x[0])

    top_k = 10
    print(f"Top {top_k} Tucson bookstores (elite-recommended) for cozy/hidden atmosphere + rare books/events:")
    print('---')
    for i, (rank_score, bid, avg_score, elite_user_count) in enumerate(ranked[:top_k], 1):
        b = business_by_id[bid]
        v = agg[bid]
        print(f"{i}. {b.get('name')}")
        print(f"   Address: {b.get('address')}, {b.get('city')}, {b.get('state')}")
        print(f"   Stars: {b.get('stars')}  Reviews: {b.get('review_count')}")
        print(f"   Elite users: {elite_user_count}  Elite hits: {v['elite_hit_count']}  Total hits: {v['total_hit_count']}  AvgVecScore: {avg_score:.4f}")
        print(f"   Categories: {b.get('categories')}")
        print(f"   Evidence (from elite prioritized, may include some non-elite):")

        # Show elite evidence first
        evid = sorted(v['evidence'], key=lambda e: (0 if e.get('elite') else 1, -float(e.get('score', 0.0))))
        for ev in evid[:5]:
            elite_tag = f"ELITE({ev['elite']})" if ev.get('elite') else 'non-elite'
            uname = ev.get('user_name') or (ev.get('user_id') or '')
            themes = ','.join(ev.get('themes') or [])
            print(f"     - [{ev['kind']}] {elite_tag} user={uname} themes={themes} score={ev['score']:.4f}")
            print(f"       "{ev['snippet']}"")
        print('---')


if __name__ == '__main__':
    main()
